import java.util.LinkedHashMap;
import java.util.Map;

public class LruCache<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;

    public LruCache(int capacity) {
        // Initial capacity, load factor 0.75f, and true for access-order (instead of insertion-order)
        super(capacity, 0.75f, true);
        this.capacity = capacity;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        // Automatically evict the eldest entry when size exceeds capacity
        return size() > capacity;
    }

    public static void main(String[] args) {
        Map<String, String> cache = new LruCache<>(2);
        cache.put("A", "1");
        cache.put("B", "2");
        cache.get("A"); // Access "A", making "B" the eldest
        cache.put("C", "3"); // Triggers eviction of "B"

        System.out.println(cache.keySet()); // Prints [A, C]
    }
}
